using Microsoft.EntityFrameworkCore;
public enum OrderStatus { Pending, Shipped, Cancelled }
public sealed record OrderRow(int Id, DateTime PlacedAt, OrderStatus Status);
public sealed record OrderCancelled(int OrderId);
public interface IEventBus
{
    Task PublishAsync<T>(T message, CancellationToken ct);
}
public interface IReadStore
{
    Task<List<OrderRow>> OrdersFor(int customerId, CancellationToken ct);
}
public sealed class Order
{
    public int Id { get; private set; }
    public int CustomerId { get; init; }
    public DateTime PlacedAt { get; init; }
    public OrderStatus Status { get; private set; }
    public void Cancel()
    {
        if (Status == OrderStatus.Shipped)
            throw new InvalidOperationException("Shipped orders can't be cancelled.");
        Status = OrderStatus.Cancelled;
    }
}
public sealed class ShopDb(DbContextOptions<ShopDb> options) : DbContext(options)
{
    public DbSet<Order> Orders => Set<Order>();
}
